steps.content:
cat > /etc/nginx/nginx.conf <<'EOF'
worker_processes auto;
pid /run/nginx.pid;
error_log /var/log/nginx/error.log;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    sendfile on;
    keepalive_timeout 65;

    log_format benchmark '$time_local $request_method $status "$http_user_agent"';
    limit_req_zone $binary_remote_addr zone=benchmark:10m rate=10r/s;

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}
EOF

mkdir -p /var/www/html /etc/nginx/conf.d
printf 'Welcome to the benchmark webserver\n' > /var/www/html/index.html
printf 'Page not found - Please check your URL\n' > /var/www/html/404.html
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark burst=10 nodelay;

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
